const svg = d3.select('body')
  .append('svg')
  .attr('width', width)
  .attr('height', height)
  .style('background', '#87CEEB'); // sky blue background

// Quadratic Bezier control point calculation
function quadraticBezierControlPoint(bottomLeft: [number, number], width: number, height: number, vx: number): [number, number] {
  const px = 0.5 * (4 * vx - 2 * bottomLeft[0] - width);
  const py = -2 * height + bottomLeft[1];
  return [px, py];
}

// Draw a hill as a quadratic bezier path with gradient fill
function drawHill(params: {bottomLeft: [number, number], width: number, height: number, vx: number, stroke: string, strokeWidth: number}) {
  const {bottomLeft, width, height, vx, stroke, strokeWidth} = params;
  const controlPoint = quadraticBezierControlPoint(bottomLeft, width, height, vx);

  // Define path
  const pathData = `M${bottomLeft[0]},${bottomLeft[1]} Q${controlPoint[0]},${controlPoint[1]} ${bottomLeft[0] + width},${bottomLeft[1]}`;

  // Define gradient
  const gradientId = 'hillGradient';
  const defs = svg.append('defs');
  const gradient = defs.append('linearGradient')
    .attr('id', gradientId)
    .attr('x1', '0')
    .attr('x2', '0')
    .attr('y1', '0')
    .attr('y2', '1');

  gradient.append('stop')
    .attr('offset', '5%')
    .attr('stop-color', '#E87E13');
  gradient.append('stop')
    .attr('offset', '95%')
    .attr('stop-color', '#E84013');

  // Draw path
  svg.append('path')
    .attr('d', pathData)
    .attr('stroke', stroke)
    .attr('stroke-width', strokeWidth)
    .attr('fill', `url(#${gradientId})`);
}

