import * as d3 from 'd3';

// ---------------------------------------------------------------------------
// 1. Interfaces and Data Structures
// ---------------------------------------------------------------------------

// Interface representing the control point of the Bezier curve
interface Point {
    x: number;
    y: number;
}

// Interface representing the full data object for a hill
interface HillData {
    bottomLeftX: number;
    bottomLeftY: number;
    width: number;
    height: number;
    controlPoint: Point;
    strokeColor: string;
    strokeWidth: number;
}

// ---------------------------------------------------------------------------
// 2. Helper Functions
// ---------------------------------------------------------------------------

/**
 * Calculates the control point for a quadratic Bezier curve to form a hill.
 * For a quadratic Bezier curve starting at (x, y) and ending at (x + w, y),
 * placing the control point at (x + w/2, y - 2*h) ensures the curve's peak 
 * reaches exactly `h` units above the baseline.
 */
function calculateControlPoint(
    bottomLeftX: number, 
    bottomLeftY: number, 
    width: number, 
    height: number
): Point {
    return {
        x: bottomLeftX + width / 2,
        y: bottomLeftY - height * 2 // Control point Y must be twice the desired height
    };
}

// ---------------------------------------------------------------------------
// 3. Configuration and Hardcoded Data
// ---------------------------------------------------------------------------

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 500;
const BASELINE_Y = 450; // The flat ground level from which hills emerge

// Raw configurations for the three hills (from background to foreground)
const rawHillsConfig = [
    { x: -50,  w: 450, h: 220, strokeW: 2 }, // Left background hill
    { x: 400,  w: 480, h: 260, strokeW: 2 }, // Right background hill
    { x: 150,  w: 550, h: 320, strokeW: 3 }  // Center foreground hill
];

// Map raw configurations into the final array of objects
const hillsData: HillData[] = rawHillsConfig.map(config => ({
    bottomLeftX: config.x,
    bottomLeftY: BASELINE_Y,
    width: config.w,
    height: config.h,
    controlPoint: calculateControlPoint(config.x, BASELINE_Y, config.w, config.h),
    strokeColor: "#8B4513", // SaddleBrown
    strokeWidth: config.strokeW
}));

// ---------------------------------------------------------------------------
// 4. SVG Setup and Rendering
// ---------------------------------------------------------------------------

// Create the main SVG container in the document body
const svg = d3.select("body")
    .append("svg")
    .attr("width", CANVAS_WIDTH)
    .attr("height", CANVAS_HEIGHT)
    .style("box-shadow", "0 4px 8px rgba(0,0,0,0.1)");

// Draw the sky blue background
svg.append("rect")
    .attr("width", CANVAS_WIDTH)
    .attr("height", CANVAS_HEIGHT)
    .attr("fill", "#87CEEB"); // Sky blue

// Define SVG definitions (for gradients)
const defs = svg.append("defs");

// Create a linear gradient for the hills
// gradientUnits="objectBoundingBox" ensures the gradient scales perfectly to each hill's size
const hillGradient = defs.append("linearGradient")
    .attr("id", "hill-gradient")
    .attr("x1", "0%")
    .attr("y1", "0%")
    .attr("x2", "0%")
    .attr("y2", "100%");

hillGradient.append("stop")
    .attr("offset", "0%")
    .attr("stop-color", "#FFB74D"); // Lighter orange (top)

hillGradient.append("stop")
    .attr("offset", "100%")
    .attr("stop-color", "#E65100"); // Darker orange (bottom)

// Render the hills
// The path 'd' uses 'M' to move to the start, 'Q' for the quadratic curve, and 'Z' to close the shape
svg.selectAll(".hill")
    .data(hillsData)
    .enter()
    .append("path")
    .attr("class", "hill")
    .attr("d", d => {
        const startX = d.bottomLeftX;
        const startY = d.bottomLeftY;
        const endX = d.bottomLeftX + d.width;
        const endY = d.bottomLeftY;
        const cpX = d.controlPoint.x;
        const cpY = d.controlPoint.y;

        return `M ${startX},${startY} Q ${cpX},${cpY} ${endX},${endY} Z`;
    })
    .attr("fill", "url(#hill-gradient)")
    .attr("stroke", d => d.strokeColor)
    .attr("stroke-width", d => d.strokeWidth);

// ---------------------------------------------------------------------------
// 5. Title Text
// ---------------------------------------------------------------------------

svg.append("text")
    .attr("x", CANVAS_WIDTH / 2)
    .attr("y", 60)
    .attr("text-anchor", "middle")
    .style("font-family", "sans-serif")
    .style("font-size", "28px") // Medium size
    .style("font-weight", "600")
    .style("fill", "#333333") // Dark gray
    .text("D3 Quadratic Bezier Hills");
