export class TraceChart {
    private container: HTMLDivElement;
    private rawData: TraceSeries[];

    constructor(containerId: string, data: TraceSeries[]) {
        const el = document.getElementById(containerId) as HTMLDivElement;
        if (!el) {
            throw new Error(`Target HTML div with id '${containerId}' not found.`);
        }
        this.container = el;
        this.rawData = data;

        // Initial render
        this.render();
    }

    /**
     * Toggles the visibility of a series and re-renders the chart
     */
    private toggleSeries = (id: string): void => {
        const series = this.rawData.find(s => s.id === id);
        if (series) {
            series.show = !series.show;
            this.render();
        }
    };

    /**
     * Main rendering routine
     */
    private render(): void {
        // Clear previous chart render
        this.container.innerHTML = "";

        // --- Data Transformation ---
        const chartDataArrays: (string | number)[][] = [];
        const seriesColorMap: Record<string, string> = {};

        this.rawData.forEach(series => {
            // "mapping of series identifiers to their respective colors is created for styling"
            seriesColorMap[series.id] = series.color;

            if (series.show) {
                // "extracting the series identifiers and their corresponding values into an array of arrays"
                chartDataArrays.push([series.id, ...series.values]);
            }
        });

        // --- Chart Dimensions & Layout ---
        const width = 600;
        const height = 400;
        const rightPadding = 40;  // Accommodates the legend
        const leftPadding = 50;
        const topPadding = 60;
        const bottomPadding = 50;

        // Plotting area calculations
        const plotWidth = width - leftPadding - rightPadding - 20; // leaves buffer for legend
        const plotHeight = height - topPadding - bottomPadding;

        // --- Scales & Boundaries ---
        let maxCycles = 0;
        let maxValue = 0;

        chartDataArrays.forEach(row => {
            const values = row.slice(1) as number[];
            if (values.length > maxCycles) maxCycles = values.length;
            values.forEach(v => { if (v > maxValue) maxValue = v; });
        });

        maxCycles = Math.max(maxCycles, 1);
        maxValue = Math.max(maxValue, 10);
        const yMax = Math.ceil(maxValue * 1.15); // Add 15% visual headroom

        const getX = (index: number) => leftPadding + (index / Math.max(1, maxCycles - 1)) * plotWidth;
        const getY = (value: number) => topPadding + plotHeight - (value / yMax) * plotHeight;

        // --- SVG Construction ---
        const svgNS = "http://www.w3.org/2000/svg";
        const svg = document.createElementNS(svgNS, "svg");
        svg.setAttribute("width", width.toString());
        svg.setAttribute("height", height.toString());
        svg.style.fontFamily = "system-ui, -apple-system, sans-serif";
        svg.style.background = "#ffffff";
        svg.style.overflow = "visible";

        // Title: "Trace.js Simulation Analysis"
        const title = document.createElementNS(svgNS, "text");
        title.setAttribute("x", (width / 2).toString());
        title.setAttribute("y", "30");
        title.setAttribute("text-anchor", "middle");
        title.setAttribute("font-size", "16px");
        title.setAttribute("font-weight", "600");
        title.setAttribute("fill", "#222");
        title.textContent = "Trace.js Simulation Analysis";
        svg.appendChild(title);

        // --- Axes & Grid ---
        const axesGroup = document.createElementNS(svgNS, "g");

        // X-Axis Line
        const xAxis = document.createElementNS(svgNS, "line");
        xAxis.setAttribute("x1", leftPadding.toString());
        xAxis.setAttribute("y1", (topPadding + plotHeight).toString());
        xAxis.setAttribute("x2", (leftPadding + plotWidth).toString());
        xAxis.setAttribute("y2", (topPadding + plotHeight).toString());
        xAxis.setAttribute("stroke", "#888");
        axesGroup.appendChild(xAxis);

        // X-Axis Label ("Cycle")
        const xLabel = document.createElementNS(svgNS, "text");
        xLabel.setAttribute("x", (leftPadding + plotWidth / 2).toString());
        xLabel.setAttribute("y", (height - 10).toString());
        xLabel.setAttribute("text-anchor", "middle");
        xLabel.setAttribute("font-size", "12px");
        xLabel.setAttribute("fill", "#555");
        xLabel.textContent = "Cycle";
        axesGroup.appendChild(xLabel);

        // Y-Axis Line
        const yAxis = document.createElementNS(svgNS, "line");
        yAxis.setAttribute("x1", leftPadding.toString());
        yAxis.setAttribute("y1", topPadding.toString());
        yAxis.setAttribute("x2", leftPadding.toString());
        yAxis.setAttribute("y2", (topPadding + plotHeight).toString());
        yAxis.setAttribute("stroke", "#888");
        axesGroup.appendChild(yAxis);

        // Y-Axis Label ("Value")
        const yLabel = document.createElementNS(svgNS, "text");
        yLabel.setAttribute("transform", "rotate(-90)");
        yLabel.setAttribute("x", (-(topPadding + plotHeight / 2)).toString());
        yLabel.setAttribute("y", "15");
        yLabel.setAttribute("text-anchor", "middle");
        yLabel.setAttribute("font-size", "12px");
        yLabel.setAttribute("fill", "#555");
        yLabel.textContent = "Value";
        axesGroup.appendChild(yLabel);

        // Grid lines and Y-Ticks
        const numYTicks = 5;
        for (let i = 0; i <= numYTicks; i++) {
            const val = (yMax / numYTicks) * i;
            const y = getY(val);

            const tickText = document.createElementNS(svgNS, "text");
            tickText.setAttribute("x", (leftPadding - 8).toString());
            tickText.setAttribute("y", (y + 4).toString());
            tickText.setAttribute("text-anchor", "end");
            tickText.setAttribute("font-size", "10px");
            tickText.setAttribute("fill", "#666");
            tickText.textContent = val.toFixed(0);
            axesGroup.appendChild(tickText);

            if (i > 0) {
                const gridLine = document.createElementNS(svgNS, "line");
                gridLine.setAttribute("x1", leftPadding.toString());
                gridLine.setAttribute("y1", y.toString());
                gridLine.setAttribute("x2", (leftPadding + plotWidth).toString());
                gridLine.setAttribute("y2", y.toString());
                gridLine.setAttribute("stroke", "#eaeaea");
                axesGroup.appendChild(gridLine);
            }
        }

        // X-Ticks
        for (let i = 0; i < maxCycles; i++) {
            const x = getX(i);
            const tickText = document.createElementNS(svgNS, "text");
            tickText.setAttribute("x", x.toString());
            tickText.setAttribute("y", (topPadding + plotHeight + 18).toString());
            tickText.setAttribute("text-anchor", "middle");
            tickText.setAttribute("font-size", "10px");
            tickText.setAttribute("fill", "#666");
            tickText.textContent = i.toString();
            axesGroup.appendChild(tickText);
        }

        svg.appendChild(axesGroup);

        // --- Plot Data Series ---
        const linesGroup = document.createElementNS(svgNS, "g");

        chartDataArrays.forEach(row => {
            const id = row[0] as string;
            const values = row.slice(1) as number[];
            const color = seriesColorMap[id];

            // Trace Line
            const path = document.createElementNS(svgNS, "path");
            let d = "";
            values.forEach((v, idx) => {
                const x = getX(idx);
                const y = getY(v);
                d += idx === 0 ? `M ${x} ${y} ` : `L ${x} ${y} `;
            });
            path.setAttribute("d", d);
            path.setAttribute("fill", "none");
            path.setAttribute("stroke", color);
            path.setAttribute("stroke-width", "2.5");
            linesGroup.appendChild(path);

            // Data Points Marked on Lines
            values.forEach((v, idx) => {
                const circle = document.createElementNS(svgNS, "circle");
