const chartWidth: number = svgWidth - margin.left - margin.right;
const chartHeight: number = svgHeight - margin.top - margin.bottom;

const barGap: number = 15;
const barWidth: number = (chartWidth / data.length) - barGap;

// Find the maximum value to calculate proportions
const maxDataValue: number = Math.max(...data);

// Create the SVG namespace and element
const svgns: string = "http://www.w3.org/2000/svg";
const svg: SVGSVGElement = document.createElementNS(svgns, "svg");

