    fontFamily: "sans-serif",
};

// 3. Helper function to create SVG elements with namespaces
const SVG_NS = "http://www.w3.org/2000/svg";
function createSVGElement(tag: string, attributes: Record<string, string | number>): SVGElement {
    const element = document.createElementNS(SVG_NS, tag);
    for (const [key, value] of Object.entries(attributes)) {
        element.setAttribute(key, value.toString());
    }
    return element;
}

// 4. Main drawing function
function drawHorizontalBarChart(data: MemberData[], config: ChartConfig): void {
    // Calculate inner dimensions
    const innerWidth = config.width - config.margin.left - config.margin.right;
    const innerHeight = config.height - config.margin.top - config.margin.bottom;

    // Create base SVG container
    const svg = createSVGElement("svg", {
        width: config.width,
        height: config.height,
        viewBox: `0 0 ${config.width} ${config.height}`,
        style: `font-family: ${config.fontFamily}; background-color: #ffffff;`,
    });

    // Create main group offset by margins
    const chartGroup = createSVGElement("g", {
        transform: `translate(${config.margin.left}, ${config.margin.top})`,
    });
    svg.appendChild(chartGroup);

    // Add Chart Title
    const titleText = createSVGElement("text", {
        x: innerWidth / 2,
        y: -20,
        "text-anchor": "middle",
        "font-size": "24px",
        "font-weight": "bold",
        fill: "#333333",
    });
    titleText.textContent = config.title;
    chartGroup.appendChild(titleText);

    // Calculate Scales
    const maxStudyCount = Math.max(...data.map(d => d.studyCount));
    // Scale X: Maps study count to pixel width
    const xScale = (value: number) => (value / maxStudyCount) * innerWidth;

    // Scale Y parameters
    const barHeight = (innerHeight / data.length) * 0.7; // 70% bar, 30% gap
    const barSpacing = (innerHeight / data.length) * 0.3;

    // --- Draw X Axis (Study Count) ---
    const xAxisLine = createSVGElement("line", {
        x1: 0, y1: innerHeight,
        x2: innerWidth, y2: innerHeight,
        stroke: "#000000",
        "stroke-width": 1
    });
    chartGroup.appendChild(xAxisLine);

    // Add X-Axis Label
