    for (let i = 0; i <= tickCount; i++) {
        const tickValue = Math.round((maxStudyCount / tickCount) * i);
        const tickX = xScale(tickValue);

        // Tick line
        const tick = createSVGElement("line", {
            x1: tickX, y1: innerHeight,
            x2: tickX, y2: innerHeight + 6,
            stroke: "#000000",
