            x: tickX, y: innerHeight + 22,
            "text-anchor": "middle",
            "font-size": "12px",
            fill: "#333333",
        });
        tickLabel.textContent = tickValue.toString();
        chartGroup.appendChild(tickLabel);
    }

    // --- Draw Y Axis (Members Line) ---
    const yAxisLine = createSVGElement("line", {
        x1: 0, y1: 0,
        x2: 0, y2: innerHeight,
        stroke: "#000000",
        "stroke-width": 1
    });
    chartGroup.appendChild(yAxisLine);

    // --- Draw Bars and Member Labels ---
    data.forEach((d, index) => {
        const yPos = index * (barHeight + barSpacing) + barSpacing / 2;
        const barWidth = xScale(d.studyCount);

        // Bar Rectangle
        const rect = createSVGElement("rect", {
            x: 0,
            y: yPos,
            width: barWidth,
            height: barHeight,
            fill: config.barColor,
            rx: 2, // slightly rounded corners for aesthetic
            ry: 2
        });
        chartGroup.appendChild(rect);

        // Member Label (Y-Axis)
        const memberLabel = createSVGElement("text", {
            x: -15, // offset to the left of the axis
            y: yPos + barHeight / 2,
            "text-anchor": "end",
            "alignment-baseline": "middle", // vertically centers the text
            "dominant-baseline": "middle",  // fallback for browser compatibility
            "font-size": "14px",
            fill: "#333333",
        });
        memberLabel.textContent = d.member;
        chartGroup.appendChild(memberLabel);
    });

    // Mount SVG to the DOM
    document.body.appendChild(svg);
}

// 5. Execute Rendering
drawHorizontalBarChart(data, config);
