### TypeScript Code

```typescript
import * as d3 from 'd3';

// 1. Define the hardcoded input data, structured in columns
const columns: [string, ...number[]][] = [
    ['data1', 25, 45, 38, 60, 80, 55, 90],
    ['data2', 15, 30, 50, 40, 65, 45, 75]
];

// Transform the column format into an array of series objects for easier mapping
const dataSeries = columns.map(col => ({
    label: col[0] as string,
    values: col.slice(1) as number[]
}));

function createLineChart() {
    // 2. Setup Dimensions and Margins
    const width = 700;
    const height = 450;
    const margin = { top: 60, right: 140, bottom: 60, left: 70 }; // Large right margin for the legend
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    // Create a wrapper div in the DOM
    const container = document.createElement('div');
    container.id = 'line-chart-container';
    document.body.appendChild(container);

    // Append the SVG object to the container
    const svg = d3.select(container)
        .append('svg')
        .attr('width', width)
        .attr('height', height)
        .style('font-family', 'sans-serif');

    const chartArea = svg.append('g')
        .attr('transform', `translate(${margin.left},${margin.top})`);

    // 3. Setup Scales
    const maxDataPoints = d3.max(dataSeries, d => d.values.length) || 0;
    const maxValue = d3.max(dataSeries.flatMap(d => d.values)) || 0;

    const xScale = d3.scaleLinear()
        .domain([0, maxDataPoints - 1])
        .range([0, innerWidth]);

    const yScale = d3.scaleLinear()
        .domain([0, maxValue * 1.1]) // Add a 10% padding to the top
        .range([innerHeight, 0]);

    // Define distinct colors for our two data sets
    const colorScale = d3.scaleOrdinal<string>()
        .domain(dataSeries.map(d => d.label))
        .range(['#1f77b4', '#ff7f0e']);

    // 4. Draw the Grid
    const makeXGridLines = () => d3.axisBottom(xScale).ticks(maxDataPoints);
    const makeYGridLines = () => d3.axisLeft(yScale).ticks(6);

    // X-Axis Grid
    chartArea.append('g')
        .attr('class', 'grid')
        .attr('transform', `translate(0,${innerHeight})`)
        .call(makeXGridLines().tickSize(-innerHeight))
        .call(g => g.select('.domain').remove())
        .call(g => g.selectAll('.tick text').remove())
        .call(g => g.selectAll('.tick line').attr('stroke', '#e4e4e4').attr('stroke-dasharray', '3,3'));

    // Y-Axis Grid
    chartArea.append('g')
        .attr('class', 'grid')
        .call(makeYGridLines().tickSize(-innerWidth))
        .call(g => g.select('.domain').remove())
        .call(g => g.selectAll('.tick text').remove())
        .call(g => g.selectAll('.tick line').attr('stroke', '#e4e4e4').attr('stroke-dasharray', '3,3'));

    // 5. Draw the Axes (with tick marks)
    const xAxis = d3.axisBottom(xScale).tickValues(d3.range(maxDataPoints));
    const yAxis = d3.axisLeft(yScale).ticks(6);

    chartArea.append('g')
        .attr('transform', `translate(0,${innerHeight})`)
        .call(xAxis);

    chartArea.append('g')
        .call(yAxis);

    // 6. Draw Axes Labels and Title
    // Title
    svg.append('text')
        .attr('x', width / 2)
        .attr('y', margin.top / 2)
        .attr('text-anchor', 'middle')
        .style('font-size', '20px')
        .style('font-weight', 'bold')
        .text('Sample Line Chart');

    // X Axis Label
    chartArea.append('text')
        .attr('x', innerWidth / 2)
        .attr('y', innerHeight + margin.bottom - 15)
        .attr('text-anchor', 'middle')
        .style('font-size', '14px')
        .text('X Axis');

    // Y Axis Label
    chartArea.append('text')
        .attr('transform', 'rotate(-90)')
        .attr('x', -innerHeight / 2)
        .attr('y', -margin.left + 20)
        .attr('text-anchor', 'middle')
        .style('font-size', '14px')
        .text('Y Axis');

    // 7. Plot the Lines and Data Points
    const lineGenerator = d3.line<number>()
        .x((_, i) => xScale(i))
        .y(d => yScale(d));

    dataSeries.forEach((series, index) => {
        // Draw the line
        chartArea.append('path')
            .datum(series.values)
            .attr('fill', 'none')
            .attr('stroke', colorScale(series.label))
            .attr('stroke-width', 2.5)
            .attr('d', lineGenerator);

        // Draw distinct marker circles on data points
        chartArea.selectAll(`.point-marker-${index}`)
            .data(series.values)
            .enter()
            .append('circle')
            .attr('class', `point-marker-${index}`)
            .attr('cx', (_, i) => xScale(i))
            .attr('cy', d => yScale(d))
            .attr('r', 5)
            .attr('fill', '#ffffff')
            .attr('stroke', colorScale(series.label))
            .attr('stroke-width', 2);
    });

    // 8. Create the Legend positioned to the right
    const legend = svg.append('g')
        .attr('transform', `translate(${width - margin.right + 25}, ${margin.top})`);

    dataSeries.forEach((series, i) => {
        const legendRow = legend.append('g')
            .attr('transform', `translate(0, ${i * 25})`);

        // Legend Color Box
        legendRow.append('rect')
            .attr('width', 12)
            .attr('height', 12)
            .attr('rx', 2) // slight rounding
            .attr('fill', colorScale(series.label));

        // Legend Label Text
        legendRow.append('text')
            .attr('x', 20)
            .attr('y', 11) // Align roughly with the center of the rect
            .attr('text-anchor', 'start')
            .style('font-size', '13px')
            .text(series.label);
    });
}

// Execute the chart generator
createLineChart();
